52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String normalizedAddress = normalizeAddress(owner.getAddress());
108	        if (normalizedAddress.isEmpty()) {
109	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
110	                "Address must not be blank after normalization");
111	        }
112	        owner.setAddress(normalizedAddress);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        validateEmailDomain(owner.getEmail());
117	        validatePostcode(owner.getPostcode(), owner.getCity());
118	        java.time.LocalDate serverDate = java.time.LocalDate.now();
119	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
120	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
121	                "Registration date must not be later than the current server date");
122	        }
123	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
124	            ? owner.getRegistrationDate() : serverDate;
125	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
126	        owner.setRegistrationDate(businessDate);
127	        long createdToday = this.clinicService.findAllOwners().stream()
128	            .map(Owner::getRegistrationDate)
129	            .filter(businessDate::equals)
130	            .count();
131	        if (createdToday >= 100) {
132	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
133	                "The maximum number of owners for today has already been reached");
134	        }
135	        owner.setBulkSignupWarning(createdToday > 80);
136	        // The household is keyed deterministically on (normalized last name, postcode): every owner
137	        // computes the same householdId from those two fields, so owners sharing a last name and
138	        // postcode belong to the same household automatically, without any explicit linking.
139	        String lastNameKey = normalizeForHousehold(owner.getLastName());
140	        String householdId = householdId(lastNameKey, owner.getPostcode());
141	        owner.setHouseholdId(householdId);
142	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
143	            .filter(existing -> householdId.equals(
144	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
145	            .toList();
146	        // All duplicate detection is expressed through the single derived identityKey
147	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
148	        String identityKey = owner.getIdentityKey();
149	        boolean identityInUse = this.clinicService.findAllOwners().stream()
150	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
151	        if (identityInUse) {
152	            throw new ResponseStatusException(HttpStatus.CONFLICT,
153	                "An owner with this identity already exists");
154	        }
155	        // Because the household is keyed on (last name, postcode), a second owner sharing a last name
156	        // and postcode with an existing owner is the same household and is rejected as a household
157	        // duplicate (409). Declaring 'sharesHousehold' only bypasses this block, creating the owner as
158	        // a declared household member.
159	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
160	        if (!householdMembers.isEmpty() && !declaredHouseholdMember) {
161	            throw new ResponseStatusException(HttpStatus.CONFLICT,
162	                "An owner in this household already exists");
163	        }
164	        String cityKey = normalizeForHousehold(owner.getCity());
165	        long cityCount = this.clinicService.findAllOwners().stream()
166	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
167	            .count();
168	        if (cityCount >= 50) {
169	            throw new ResponseStatusException(HttpStatus.CONFLICT,
170	                "This city already has the maximum number of owners");
171	        }
172	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
173	        owner.setHouseholdSize(householdMembers.size() + 1);
174	        // The former soft-match (same last name and postcode, different telephone) now coincides
175	        // exactly with the household key: such an owner is either rejected as a household duplicate
176	        // above, or, when it declares 'sharesHousehold', created as a declared household member. A
177	        // declared member is not a suspected duplicate, so no owner is ever flagged here.
178	        owner.setPossibleDuplicate(false);
179	        owner.setPossibleDuplicateOf(null);
180	        owner.setCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
181	            owner.getTelephone(), owner.getLastName()));
182	        this.clinicService.saveOwner(owner);
183	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
184	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
185	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
186	        headers.setLocation(UriComponentsBuilder.newInstance()
187	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
188	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    /**
192	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
193	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
194	     * to the effective registration date (whether supplied in the request or defaulted to the server
195	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
196	     * business day.
197	     *
198	     * @param date the effective registration date
199	     * @return the same date if it is a weekday, otherwise the following Monday
200	     */
201	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
202	        return switch (date.getDayOfWeek()) {
203	            case SATURDAY -> date.plusDays(2);
204	            case SUNDAY -> date.plusDays(1);
205	            default -> date;
206	        };
207	    }
208	
209	    /**
210	     * Counts the owners that already exist (before the current create) whose first and last names
211	     * both match the supplied names, compared case-insensitively. The returned value is captured on
212	     * the new owner at creation time and does not change as further owners are added later.
213	     *
214	     * @param firstName the new owner's first name
215	     * @param lastName  the new owner's last name
216	     * @return the number of pre-existing namesake owners
217	     */
218	    private int namesakeCount(String firstName, String lastName) {
219	        return (int) this.clinicService.findAllOwners().stream()
220	            .filter(existing -> existing.getFirstName() != null
221	                && existing.getFirstName().equalsIgnoreCase(firstName)
222	                && existing.getLastName() != null
223	                && existing.getLastName().equalsIgnoreCase(lastName))
224	            .count();
225	    }
226	
227	    /**
228	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
229	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
230	     * the city when the postcode is absent or in no known range, see
231	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
232	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
233	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
234	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
235	     * a pure function of the owner's region, telephone and last name.
236	     *
237	     * @param city                the owner's city
238	     * @param postcode            the owner's postcode, may be {@code null}
239	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
240	     * @param lastName            the owner's last name
241	     * @return the assigned customer code
242	     */
243	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
244	        String region = org.springframework.samples.petclinic.mapper.Localities
245	            .forCityAndPostcode(city, postcode);
246	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
247	            + (lastName == null ? "" : lastName), 8);
248	        return region + "-" + hash8;
249	    }
250	
251	    /**
252	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
253	     * UTF-8 bytes of {@code value}.
254	     *
255	     * @param value  the source value to hash
256	     * @param length the number of leading hex characters to return
257	     * @return the leading upper-case hex characters of the digest
258	     */
259	    private String sha256UpperHex(String value, int length) {
260	        try {
261	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
262	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
263	            StringBuilder sb = new StringBuilder(digest.length * 2);
264	            for (byte b : digest) {
265	                sb.append(String.format("%02x", b));
266	            }
267	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
268	        }
269	        catch (java.security.NoSuchAlgorithmException e) {
270	            throw new IllegalStateException("SHA-256 not available", e);
271	        }
272	    }
273	
274	    /**
275	     * Normalizes a street address applied whenever an owner is created: leading and trailing
276	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
277	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
278	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
279	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
280	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
281	     * {@code '12 MAIN STREET'}.
282	     *
283	     * @param address the raw address as submitted, or {@code null} when absent
284	     * @return the normalized address, or the empty string when the value is blank
285	     */
286	    private String normalizeAddress(String address) {
287	        String collapsed = (address == null ? "" : address)
288	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
289	        if (collapsed.isEmpty()) {
290	            return "";
291	        }
292	        String[] tokens = collapsed.split(" ");
293	        for (int i = 0; i < tokens.length; i++) {
294	            switch (tokens[i]) {
295	                case "ST" -> tokens[i] = "STREET";
296	                case "RD" -> tokens[i] = "ROAD";
297	                case "AVE" -> tokens[i] = "AVENUE";
298	                default -> { }
299	            }
300	        }
301	        return String.join(" ", tokens);
302	    }
303	
304	    /**
305	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
306	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
307	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
308	     * empty string.
309	     *
310	     * @param value the raw value (last name or address) as submitted
311	     * @return the normalized comparison key
312	     */
313	    private String normalizeForHousehold(String value) {
314	        if (value == null) {
315	            return "";
316	        }
317	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
318	    }
319	
320	    /**
321	     * Derives the stable shared household identifier for a household, keyed on the normalized last
322	     * name and address. Because it is a pure function of those normalized keys, every owner in the
323	     * same household deterministically computes the same value. The identifier is the first 12
324	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
325	     * (the separator prevents distinct name/address pairs from colliding).
326	     *
327	     * @param lastNameKey the normalized last-name comparison key
328	     * @param addressKey  the normalized address comparison key
329	     * @return the stable household identifier
330	     */
331	    private String householdId(String lastNameKey, String postcode) {
332	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
333	        try {
334	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
335	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
336	            StringBuilder sb = new StringBuilder(digest.length * 2);
337	            for (byte b : digest) {
338	                sb.append(String.format("%02x", b));
339	            }
340	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
341	        }
342	        catch (java.security.NoSuchAlgorithmException e) {
343	            throw new IllegalStateException("SHA-256 not available", e);
344	        }
345	    }
346	
347	    /**
348	     * The exact number of national (subscriber) digits required for a given country calling code,
349	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
350	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
351	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
352	     */
353	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
354	        java.util.Map.of("61", 9, "1", 10);
355	
356	    /**
357	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
358	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
359	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
360	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
361	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
362	     * is stored as {@code '+61412345678'}.
363	     *
364	     * <p>In addition, when the number's country code has a fixed national-number length (see
365	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
366	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
367	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
368	     *
369	     * @param telephone the raw telephone number as submitted
370	     * @return the normalized E.164 telephone number
371	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
372	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
373	     *         for its country code
374	     */
375	    private String normalizeTelephone(String telephone) {
376	        String raw = telephone == null ? "" : telephone.trim();
377	        String digits = raw.replaceAll("\\D", "");
378	        String e164;
379	        if (raw.startsWith("+")) {
380	            e164 = "+" + digits;
381	        } else {
382	            if (digits.startsWith("0")) {
383	                digits = digits.substring(1);
384	            }
385	            e164 = "+61" + digits;
386	        }
387	        int digitCount = e164.length() - 1;
388	        if (digitCount < 8 || digitCount > 15) {
389	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
390	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
391	        }
392	        validateNationalNumberLength(e164);
393	        return e164;
394	    }
395	
396	    /**
397	     * Validates that an E.164 number's national-number length is correct for its country code.
398	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
399	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
400	     * following it must match exactly. Country codes without a fixed length are left unchecked.
401	     *
402	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
403	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
404	     *         for the country code
405	     */
406	    private void validateNationalNumberLength(String e164) {
407	        String allDigits = e164.substring(1);
408	        String bestCode = null;
409	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
410	            if (allDigits.startsWith(code)
411	                    && (bestCode == null || code.length() > bestCode.length())) {
412	                bestCode = code;
413	            }
414	        }
415	        if (bestCode == null) {
416	            return;
417	        }
418	        int nationalLength = allDigits.length() - bestCode.length();
419	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
420	        if (nationalLength != required) {
421	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
422	                "Telephone for country code '+" + bestCode + "' must have " + required
423	                    + " national digits");
424	        }
425	    }
426	
427	    /**
428	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
429	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
430	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
431	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
432	     */
433	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
434	        "NSW", new int[] {2000, 2099},
435	        "VIC", new int[] {3000, 3099},
436	        "QLD", new int[] {4000, 4099});
437	
438	    /**
439	     * Validates an owner's optional postcode against their city's region. The postcode is only
440	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
441	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
442	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
443	     * postcode must fall within that region's inclusive range; a city with no known region accepts
444	     * any 4-digit postcode.
445	     *
446	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
447	     * @param city     the owner's city, used to derive the region whose range applies
448	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
449	     *         for the city's region
450	     */
451	    private void validatePostcode(String postcode, String city) {
452	        if (postcode == null) {
453	            return;
454	        }
455	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
456	        int[] range = REGION_POSTCODE_RANGES.get(region);
457	        if (range == null) {
458	            return;
459	        }
460	        int value = Integer.parseInt(postcode);
461	        if (value < range[0] || value > range[1]) {
462	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
463	                "Postcode " + postcode + " is not valid for region " + region);
464	        }
465	    }
466	
467	    /**
468	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
469	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
470	     * (absent) or already valid.
471	     *
472	     * @param email the email address as submitted, or {@code null} when absent
473	     * @return the lower-cased email, or {@code null} when absent
474	     */
475	    private String normalizeEmail(String email) {
476	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
477	    }
478	
479	    /**
480	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
481	     * providers are rejected because they cannot be relied on for durable contact.
482	     */
483	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
484	        "mailinator.com", "tempmail.com", "guerrillamail.com");
485	
486	    /**
487	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
488	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
489	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
490	     * (absent) is accepted, keeping the field optional.
491	     *
492	     * @param email the normalized email address, or {@code null} when absent
493	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
494	     */
495	    private void validateEmailDomain(String email) {
496	        if (email == null) {
497	            return;
498	        }
499	        int at = email.lastIndexOf('@');
500	        if (at < 0) {
501	            return;
502	        }
503	        String domain = email.substring(at + 1);
504	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
505	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
506	                "Email domain " + domain + " is not allowed");
507	        }
508	    }
509	
510	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
511	    @Override
512	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
513	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
514	        if (currentOwner == null) {
515	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
516	        }
517	        currentOwner.setAddress(ownerFieldsDto.getAddress());
