5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's canonical region ("locality"). The postcode is preferred:
9	 * a 4-digit postcode is matched against each region's inclusive range first, and
10	 * only when the postcode is absent or in no known range does derivation fall back
11	 * to a fixed city-to-region table. Kept as a plain utility (rather than a mapper
12	 * method) so MapStruct does not treat it as an implicit {@code String -> String}
13	 * mapping.
14	 */
15	public final class Localities {
16	
17	    /** City -> canonical region. Anything not listed derives {@link #UNKNOWN}. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	        "Sydney", "NSW",
20	        "Melbourne", "VIC",
21	        "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    /** Region returned for a city that is absent from {@link #CITY_REGION}. */
30	    public static final String UNKNOWN = "UNKNOWN";
31	
32	    private Localities() {
33	    }
34	
35	    /**
36	     * Returns the canonical region for {@code city} from the fixed table
37	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
38	     * or {@code "UNKNOWN"} when the city is {@code null} or not in the table.
39	     *
40	     * @param city the owner's city
41	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
42	     */
43	    public static String forCity(String city) {
44	        if (city == null) {
45	            return UNKNOWN;
46	        }
47	        return CITY_REGION.getOrDefault(city, UNKNOWN);
48	    }
49	
50	    /**
51	     * Returns the canonical region, preferring the {@code postcode}: it is matched
52	     * against each region's inclusive postcode range first (NSW 2000-2099,
53	     * VIC 3000-3099, QLD 4000-4099). Only when the postcode is {@code null},
54	     * non-numeric, or in no known range does derivation fall back to the
55	     * {@link #forCity(String) city-to-region table}. This returns the same region
56	     * for known cities but disambiguates cities that share a name.
57	     *
58	     * @param city the owner's city
59	     * @param postcode the owner's postcode, may be {@code null}
60	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
61	     */
62	    public static String forCityAndPostcode(String city, String postcode) {
63	        String region = forPostcode(postcode);
64	        if (region != null) {
65	            return region;
66	        }
67	        return forCity(city);
68	    }
69	
70	    /**
71	     * Returns the owner's canonical region ("locality"), sourced from the region-and-hash
72	     * {@code customerCode} identity: the {@code <REGION>} prefix of the {@code customerCode}
73	     * (the part before the first {@code '-'}) when one has been assigned, so the locality is
74	     * exactly the region the identity was built on. When the owner has no customer code yet
75	     * (for example seed data created before the identity was assigned) derivation falls back to
76	     * {@link #forCityAndPostcode(String, String)} over the owner's city and postcode, which
77	     * computes the same region the identity would have used.
78	     *
79	     * @param owner the owner whose locality is required
80	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
81	     */
82	    public static String forOwner(Owner owner) {
83	        String customerCode = owner.getCustomerCode();
84	        if (customerCode != null) {
85	            int dash = customerCode.indexOf('-');
86	            if (dash > 0) {
87	                return customerCode.substring(0, dash);
88	            }
89	        }
90	        return forCityAndPostcode(owner.getCity(), owner.getPostcode());
91	    }
92	
93	    /**
94	     * Returns the region whose inclusive postcode range contains {@code postcode},
95	     * or {@code null} when the postcode is {@code null}, non-numeric, or in no
96	     * known range.
97	     */
98	    private static String forPostcode(String postcode) {
99	        if (postcode == null) {
100	            return null;
101	        }
102	        int value;
103	        try {
104	            value = Integer.parseInt(postcode.trim());
105	        }
106	        catch (NumberFormatException ex) {
107	            return null;
108	        }
109	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
110	            int[] range = entry.getValue();
111	            if (value >= range[0] && value <= range[1]) {
112	                return entry.getKey();
113	            }
114	        }
115	        return null;
116	    }
117	}
